  'pantalla.tecFraseParaElAgente': { es: 'configurá las pruebas de mi proyecto en la configuración del arnés (la receta está en la sección «Tu tecnología» de guides/organization-site.md del arnés)', en: 'set up my project\'s tests in the harness configuration (the recipe is in the «Your technology» section of the harness guides/organization-site.en.md)' },
  'pantalla.tecPegaEstaFrase': { es: 'Pegá esta frase en Claude Code o Codex, abierto en el proyecto (si el navegador lo permitió, ya está copiada):', en: 'Paste this into Claude Code or Codex, opened in the project (if your browser allowed it, it is already copied):' },
  'pantalla.tecElAgenteMira': { es: 'El agente mira qué herramienta usa el proyecto, completa los datos y crea un pedido de cambio (un pull request) en el repo del equipo. Un admin lo aprueba y después la herramienta aparece en esta lista, donde la podés cambiar.', en: 'The agent looks at which tool the project uses, fills in the details and opens a pull request in the team repo. An admin approves it and then the tool shows up in this list, where you can change it.' },
  'pantalla.tecReglasDeTuEquipo': { es: '3. Reglas de tu equipo', en: '3. Your team\'s rules' },
  'pantalla.tecEstiloDeNombres': { es: '¿Los nombres de las pruebas siguen un estilo?', en: 'Do test names follow a style?' },
  'pantalla.tecSinDeclararCualquiera': { es: 'Sin definir (cualquier nombre sirve)', en: 'Not set (any name works)' },
