  'paso.0.objetivo': { es: 'Revisa que se pueda arrancar: la rama, otra sesión sobre el mismo repo, la historia lista.', en: 'Checks that it can start: the branch, another session on the same repo, the story is ready.' },
  'paso.0b.objetivo': { es: 'Abre el reloj de horas con el título de la historia.', en: 'Starts the time tracker with the story title.' },
  'paso.0c.objetivo': { es: 'Marca el pedido de trabajo de la historia como activo.', en: 'Marks the story work item as active.' },
  'paso.1.objetivo': { es: 'Lee la historia y la frena si le faltan criterios, pruebas o archivos.', en: 'Reads the story and stops it if criteria, tests or files are missing.' },
  'paso.2.objetivo': { es: 'Arma el plan de implementación, sin tocar código.', en: 'Drafts the implementation plan, without touching code.' },
  'paso.3.objetivo': { es: 'Muestra el plan y espera tu aprobación; uno de riesgo bajo se aprueba solo.', en: 'Shows the plan and waits for your approval; a low-risk one approves itself.' },
  'paso.4.objetivo': { es: 'Escribe las pruebas primero, después el código, y corre la suite.', en: 'Writes the tests first, then the code, and runs the suite.' },
  'paso.5.objetivo': { es: 'Lanza en paralelo los revisores que corresponden a este cambio.', en: 'Runs, in parallel, the reviewers this change calls for.' },
  'paso.5b.objetivo': { es: 'Intenta romper el cambio ejecutándolo; lo que confirma pasa a ser una prueba.', en: 'Tries to break the change by running it; whatever it confirms becomes a test.' },
  'paso.6.objetivo': { es: 'Junta lo que dijeron los revisores en un informe.', en: 'Gathers what the reviewers said into one report.' },
  'paso.7.objetivo': { es: 'Sólo si hay algo grave: te pregunta qué hacer.', en: 'Only if something is serious: asks you what to do.' },
  'paso.7b.objetivo': { es: 'Si hubo arreglos, vuelven a correr los revisores de lo que cambió.', en: 'If there were fixes, the reviewers of what changed run again.' },
  'paso.7c.objetivo': { es: 'Prueba cada criterio contra la aplicación real.', en: 'Tests each criterion against the real app.' },
  'paso.8.objetivo': { es: 'Arma el mensaje del commit; no commitea.', en: 'Writes the commit message; does not commit.' },
  'paso.9.objetivo': { es: 'Después del merge, deja constancia del cierre donde tu organización la lleva.', en: 'After the merge, records the closure wherever your organization keeps it.' },
