  'control.@tcg:harness-bootstrap-heal.sh': { es: 'Repara la línea de arranque del arnés cuando quedó incompleta y no se actualiza sola.', en: 'Repairs the harness startup line when it is incomplete and cannot update itself.' },
  'control.@tcg:lane-llm-notice.js': { es: 'Avisa cuántas veces el modelo abrió un permiso que el freno había cerrado.', en: 'Warns how many times the model opened a permission the safeguard had closed.' },
  'control.@int:instincts/scripts/instinct-observe.js': { es: 'Graba de fondo una línea saneada por cada herramienta usada, para encontrar lo que el equipo repite.', en: 'Quietly records one sanitized line per tool used, to find what the team keeps repeating.' },
  'control.@int:instincts/scripts/instincts-notice.js': { es: 'Te dice una vez qué graba la grabadora de instintos, adónde sube y cómo bajarte.', en: 'Tells you once what the instinct recorder captures, where it uploads it and how to opt out.' },
